-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 1
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 1 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 01', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 01 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-01.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique, em uma frase, qual é o objetivo de testar uma interface web.', 0.2, 'Testar é **produzir evidência** de que o software **atende aos requisitos**, encontrando os problemas **antes que o usuário** os encontre.', 'Palavras-chave: evidência; atende aos requisitos; antes do usuário/cliente. Nota cheia (0,2): objetivo com a ideia de evidência/requisitos e antes do usuário. Metade (0,1): só "encontrar bugs" sem ligar aos requisitos ou ao usuário. Zero (0): "provar que não tem defeitos" ou "deixar a tela bonita".'),
      (v_atividade, 1, 2, 'Diga se a frase do líder está certa ou errada e justifique com o que o teste prova e o que ele não prova.', 0.4, 'A frase está **errada**. Testar **não prova a ausência de defeitos**: mostra que os **defeitos procurados não estão lá**. Testes aprovados indicam que os cenários testados funcionam, mas podem existir defeitos em cenários que não foram testados.', 'Palavras-chave: errada/falsa; não prova ausência de defeitos; só os defeitos procurados; cenários não testados. Nota cheia (0,4): diz que está errada e justifica com o que o teste prova e não prova. Metade (0,2): diz que está errada com justificativa vaga ("sempre pode ter bug") sem explicar o limite do teste. Zero (0): concorda com o líder.'),
      (v_atividade, 1, 3, 'Explique como a equipe deve escolher o que testar, já que não dá para testar tudo, e dê um exemplo de funcionalidade da loja que deve ser testada primeiro, justificando.', 0.4, 'O que testar é escolhido **pelos requisitos e pelos riscos** (impacto e chance de dar problema). Exemplo: testar primeiro o **checkout/pagamento** (ou carrinho, login), porque uma falha ali faz a loja **perder vendas** e afeta todos os clientes.', 'Palavras-chave: requisitos; riscos/impacto; exemplo crítico (checkout, pagamento, carrinho, login); justificativa pelo prejuízo. Nota cheia (0,4): critério (requisitos e riscos) + exemplo crítico justificado. Metade (0,2): só o critério ou só o exemplo justificado. Zero (0): critério sem sentido ("o mais fácil", "o mais bonito") sem exemplo coerente.'),
      (v_atividade, 2, 1, 'Diga o que é o erro, o defeito e a falha nessa situação (um de cada).', 0.2, '**Erro:** a pessoa programadora entendeu que o CEP tem 9 dígitos (engano humano). **Defeito:** a validação no código aceita só 9 dígitos. **Falha:** o cliente digita um CEP válido de 8 dígitos e vê "CEP inválido".', 'Palavras-chave: erro = engano/entendimento; defeito = validação/código; falha = mensagem vista pelo cliente. Nota cheia (0,2): os três corretos. Metade (0,1): dois corretos. Zero (0): um ou nenhum correto.'),
      (v_atividade, 2, 2, 'Explique a relação entre os três conceitos (qual causa qual) e por que nem todo defeito vira falha.', 0.4, 'O **erro gera o defeito**, e o **defeito, quando executado, provoca a falha**. Nem todo defeito vira falha porque o trecho com defeito **pode nunca ser executado** (ou a condição que o dispara não acontece); mesmo assim ele é um **risco**.', 'Palavras-chave: erro → defeito → falha; executado; trecho que não roda; risco. Nota cheia (0,4): a cadeia na ordem certa e o motivo de nem todo defeito virar falha. Metade (0,2): só a cadeia ou só o motivo. Zero (0): ordem invertida (falha gera erro).'),
      (v_atividade, 2, 3, 'Proponha um teste que teria encontrado esse problema antes do cliente: o dado usado, o resultado esperado e o resultado que seria obtido.', 0.4, 'Teste: digitar um **CEP válido de 8 dígitos** (ex.: 89160-000 / 89160000) no cadastro. **Resultado esperado:** o CEP é aceito. **Resultado obtido** (com o defeito): mensagem "CEP inválido". Pode citar também um caso inválido (7 dígitos → deve recusar).', 'Palavras-chave: CEP de 8 dígitos; resultado esperado aceito; resultado obtido "CEP inválido". Nota cheia (0,4): dado de 8 dígitos + esperado + obtido. Metade (0,2): falta o esperado ou o obtido, ou usa dado que não revela o defeito. Zero (0): sem dado de teste ou teste sem relação com o CEP.'),
      (v_atividade, 3, 1, 'Escreva o erro, o defeito e a falha dessa situação.', 0.2, '**Erro:** alguém achou que a API devolvia o preço como número. **Defeito:** a função de formatação faz contas com o texto ("R$ 59,90") sem converter. **Falha:** a vitrine mostra "NaN" no lugar do preço.', 'Palavras-chave: suposição errada sobre a API; função faz conta com texto; "NaN" na vitrine. Nota cheia (0,2): os três corretos. Metade (0,1): dois corretos. Zero (0): um ou nenhum.'),
      (v_atividade, 3, 2, 'Diga qual tipo de teste (4.1 a 4.5) e qual camada da pirâmide (unitário, integração ou E2E) seria mais adequada para encontrar esse defeito, justificando.', 0.4, 'Tipo: **funcionalidade (4.1)** — o preço deve ser exibido corretamente, como o requisito pede. Camada: **teste unitário** da função de formatação, passando um preço em texto e um em número e conferindo o resultado; é rápido e isola a função. (Aceitar integração se justificar com o dado vindo da API simulada.)', 'Palavras-chave: funcionalidade; unitário (ou integração com API simulada); função de formatação; entrada e resultado. Nota cheia (0,4): tipo + camada coerentes + justificativa. Metade (0,2): tipo e camada sem justificativa, ou um deles errado com justificativa coerente. Zero (0): desempenho/manutenibilidade e E2E sem justificativa coerente.'),
      (v_atividade, 3, 3, 'Explique por que esse defeito, mesmo que só apareça em alguns produtos, deve ser tratado como risco e não pode ser ignorado.', 0.4, 'Todo defeito é um **risco**: mesmo aparecendo só em alguns produtos, ele já causa **falha** para clientes (preço ilegível, perda de **vendas** e de **confiança**) e pode se espalhar para outros produtos quando a API mudar. Quanto mais tarde for corrigido, **mais caro** fica.', 'Palavras-chave: risco; falha para o cliente; vendas/confiança; pode aumentar; custo maior depois. Nota cheia (0,4): risco + impacto no cliente/negócio + justificativa. Metade (0,2): só "é um risco" ou só o impacto. Zero (0): diz que pode ser ignorado.'),
      (v_atividade, 4, 1, 'Explique o que diz a Regra de 10 de Myers.', 0.2, 'A **Regra de 10 de Myers** diz que o **custo de corrigir um defeito cresce cerca de 10 vezes a cada fase** em que ele avança (requisito → código → teste → produção).', 'Palavras-chave: custo; 10 vezes; a cada fase. Nota cheia (0,2): custo cresce ~10× por fase. Metade (0,1): "quanto mais tarde, mais caro" sem a ideia de 10× por fase. Zero (0): "10 testes por sistema" ou outro sentido.'),
      (v_atividade, 4, 2, 'Compare o custo de corrigir esse requisito ambíguo agora (na conversa) com o custo de corrigi-lo em produção, citando pelo menos dois prejuízos de produção.', 0.4, 'Agora, no requisito, custa **minutos de conversa**. Em produção custa muito mais: **vendas perdidas** (desconto errado ou não aplicado), **suporte** a reclamações, **correção urgente**, **nova publicação**, retrabalho de testes e prejuízo à imagem da loja.', 'Palavras-chave: barato agora (conversa); produção: vendas, suporte, correção urgente, nova publicação, imagem. Nota cheia (0,4): comparação + pelo menos dois prejuízos de produção. Metade (0,2): comparação com só um prejuízo, ou prejuízos sem comparar com o custo agora. Zero (0): defende deixar para depois.'),
      (v_atividade, 4, 3, 'Reescreva o requisito de forma verificável (com valor e regra claros) e explique por que a nova escrita reduz o risco de defeito.', 0.4, 'Exemplo: "**Compras com subtotal a partir de R$ 200,00 recebem 10% de desconto**, calculado antes do frete; abaixo de R$ 200,00 não há desconto". A escrita com **valor e regra claros** é **verificável**: dá para escrever o teste (R$ 199,99 sem desconto; R$ 200,00 com 10%) e todos entendem o mesmo, evitando o erro de interpretação que gera o defeito.', 'Palavras-chave: valor mínimo; percentual/regra; verificável; dá para testar; evita interpretação diferente. Nota cheia (0,4): requisito com valor e regra + explicação do porquê reduz o risco. Metade (0,2): requisito melhorado sem explicação, ou explicação com requisito ainda vago. Zero (0): requisito continua ambíguo.'),
      (v_atividade, 5, 1, 'Escreva a pergunta que resume a verificação e a pergunta que resume a validação.', 0.2, 'Verificação: "**Estamos construindo o produto certo conforme a especificação?**" Validação: "**É o produto que o usuário precisa?**"', 'Palavras-chave: conforme a especificação/requisito; necessidade do usuário. Nota cheia (0,2): as duas perguntas corretas. Metade (0,1): uma correta. Zero (0): trocadas ou ausentes.'),
      (v_atividade, 5, 2, 'Diga qual parte da situação é verificação e qual é validação, e se a tela passou ou falhou em cada uma, justificando.', 0.4, '**Verificação:** conferir que o campo recusa senhas com menos de 8 caracteres → **passou** (atende ao requisito). **Validação:** a sessão com usuários reais em que 4 de 10 desistiram → **falhou**, porque a tela não atende à necessidade do usuário (ele não sabe a regra).', 'Palavras-chave: verificação passou (requisito de 8 caracteres); validação falhou (usuários desistiram). Nota cheia (0,4): identifica as duas partes e o resultado de cada com justificativa. Metade (0,2): identifica as partes sem o resultado, ou acerta uma só. Zero (0): inverte verificação e validação.'),
      (v_atividade, 5, 3, 'Diga quando cada uma acontece no desenvolvimento e proponha uma mudança na tela para que ela também passe na validação.', 0.4, 'A **verificação** acontece **durante todo o desenvolvimento** (comparando com requisitos e protótipo); a **validação**, com o **produto ou protótipo em uso** pelo usuário. Mudança: mostrar a **regra da senha** ao lado do campo ("mínimo de 8 caracteres") e uma **mensagem clara** quando a senha não atende (ou um indicador de força).', 'Palavras-chave: verificação durante o desenvolvimento; validação com usuário/em uso; mostrar a regra/mensagem clara. Nota cheia (0,4): quando de cada uma + mudança coerente. Metade (0,2): só o quando ou só a mudança. Zero (0): mudança que não ajuda o usuário (ex.: aumentar para 12 caracteres sem informar).'),
      (v_atividade, 6, 1, 'Diga se a tela passa na verificação e se passa na validação.', 0.2, '**Passa na verificação** (bloqueia após 3 tentativas, como o requisito pede) e **falha na validação** (o usuário não entende o que aconteceu e desiste).', 'Palavras-chave: passa na verificação; falha na validação. Nota cheia (0,2): as duas certas. Metade (0,1): uma certa. Zero (0): as duas erradas.'),
      (v_atividade, 6, 2, 'Classifique pelos tipos de testes (4.1 a 4.5): o bloqueio após 3 tentativas, a mensagem clara para o usuário e o desbloqueio continuar funcionando mesmo se o e-mail de recuperação demorar.', 0.4, 'Bloqueio após 3 tentativas = **funcionalidade (4.1)**; mensagem clara = **usabilidade (4.2)**; desbloqueio funcionar mesmo com demora do e-mail = **confiabilidade (4.3)**.', 'Palavras-chave: funcionalidade; usabilidade; confiabilidade. Nota cheia (0,4): os três corretos. Metade (0,2): dois corretos. Zero (0): um ou nenhum.'),
      (v_atividade, 6, 3, 'Escreva a mensagem que você recomendaria incluir no requisito e explique por que ela resolve o problema de validação.', 0.4, 'Exemplo: "**Acesso bloqueado por 15 minutos. Use ''Esqueci minha senha'' para entrar agora.**" Resolve a validação porque **explica ao usuário o que aconteceu, por quanto tempo e o que fazer**, evitando que ele ache que o site travou e desista.', 'Palavras-chave: mensagem com o motivo (bloqueio), tempo ou caminho (esqueci minha senha); explica e orienta o usuário. Nota cheia (0,4): mensagem clara + justificativa ligada ao usuário/validação. Metade (0,2): mensagem vaga ("Erro") com justificativa, ou boa mensagem sem justificativa. Zero (0): sem mensagem ou mensagem que não orienta.'),
      (v_atividade, 7, 1, 'Classifique cada um dos 5 relatos em um tipo de teste: funcionalidade, usabilidade, confiabilidade, desempenho ou manutenibilidade.', 0.2, '(1) cupom errado = **funcionalidade**; (2) 6 s no 4G = **desempenho**; (3) data sem teclado = **usabilidade**; (4) carrinho apagado quando a API cai = **confiabilidade**; (5) teste quebra com classe CSS = **manutenibilidade**.', 'Palavras-chave: as 5 classificações. Nota cheia (0,2): 5 ou 4 corretas. Metade (0,1): 2 ou 3 corretas. Zero (0): 0 ou 1 correta.'),
      (v_atividade, 7, 2, 'Escreva a pergunta que cada um dos 5 tipos de testes responde.', 0.4, 'Funcionalidade: **faz o que o requisito pede?** Usabilidade: **o usuário consegue usar com facilidade?** Confiabilidade: **continua funcionando quando algo dá errado?** Desempenho: **responde no tempo esperado?** Manutenibilidade: **é fácil de alterar sem quebrar?**', 'Palavras-chave: as 5 perguntas. Nota cheia (0,4): 5 ou 4 corretas. Metade (0,2): 2 ou 3 corretas. Zero (0): 0 ou 1.'),
      (v_atividade, 7, 3, 'Escolha dois dos relatos e escreva, para cada um, um teste que confirmaria a correção (o que fazer na tela e o resultado esperado).', 0.4, 'Exemplos: (1) aplicar o cupom de 10% num carrinho de R$ 100,00 → **total esperado R$ 90,00**; (2) abrir a página do produto simulando 4G → **carrega em até 2,5 s**; (3) digitar a data pelo teclado → **campo aceita** e mostra a data; (4) simular a API de frete fora do ar → **aviso na tela e carrinho mantido**; (5) mudar a classe CSS → **teste continua passando** (seleciona pelo texto/papel do elemento).', 'Palavras-chave: ação na tela + resultado esperado mensurável, para 2 relatos. Nota cheia (0,4): dois testes com ação e resultado esperado. Metade (0,2): um teste completo, ou dois sem resultado esperado claro. Zero (0): nenhum teste coerente.'),
      (v_atividade, 8, 1, 'Descreva o que fica na base, no meio e no topo da pirâmide de testes.', 0.2, '**Base:** muitos **testes unitários**, rápidos, de funções isoladas. **Meio:** **testes de integração** de componentes com DOM, eventos e API simulada. **Topo:** poucos **testes E2E** dos fluxos críticos no navegador real.', 'Palavras-chave: base unitário (muitos); meio integração; topo E2E (poucos). Nota cheia (0,2): as três camadas na ordem certa. Metade (0,1): camadas certas sem a ideia de quantidade, ou duas certas. Zero (0): ordem invertida.'),
      (v_atividade, 8, 2, 'Explique o que é o "cone de sorvete" (pirâmide invertida) e por que ele deixa a suíte da equipe lenta e instável.', 0.4, 'O **cone de sorvete** é a pirâmide **invertida**: **muitos E2E e poucos unitários**, como na suíte da equipe. Fica **lenta** porque cada E2E abre o navegador e percorre o fluxo inteiro, e **instável** porque depende de rede, tempo de carregamento e muitas partes ao mesmo tempo (falha "às vezes").', 'Palavras-chave: invertida; muitos E2E/poucos unitários; lento; instável (dependências, rede, tempo). Nota cheia (0,4): definição + por que lenta e instável. Metade (0,2): só a definição ou só a explicação. Zero (0): descreve a pirâmide correta como problema.'),
      (v_atividade, 8, 3, 'Classifique em unitário, integração ou E2E: a função calcularDesconto(), a máscara de CPF durante a digitação, o envio de formulário para uma API simulada e a compra completa da vitrine até a confirmação; justifique um deles.', 0.4, '`calcularDesconto()` = **unitário**; máscara de CPF = **unitário** (função) ou **integração** (campo com evento de digitação); formulário para API simulada = **integração**; compra completa = **E2E**. Justificativa exemplo: a compra completa é E2E porque percorre várias telas no navegador real como o usuário.', 'Palavras-chave: unitário; integração; E2E; uma justificativa. Nota cheia (0,4): as quatro classificações aceitáveis + uma justificativa. Metade (0,2): três corretas, ou quatro sem justificativa. Zero (0): duas ou menos corretas.'),
      (v_atividade, 9, 1, 'Diga qual camada da pirâmide deve ser a mais forte no app de crédito e por quê.', 0.2, 'No app de crédito a camada mais forte deve ser a **base de testes unitários**, porque **juros, regras fiscais e simulações são regras matemáticas** que precisam ser testadas com muitos valores, de forma rápida e isolada.', 'Palavras-chave: unitários; regras matemáticas/cálculos; muitos casos; rápido. Nota cheia (0,2): unitário + motivo. Metade (0,1): unitário sem motivo. Zero (0): E2E ou integração como camada principal.'),
      (v_atividade, 9, 2, 'Para o app de música, proponha 3 testes unitários, 2 de integração e 1 jornada E2E (um exemplo de cada, em uma linha).', 0.4, 'Exemplos — **Unitários:** validar e-mail; calcular a duração total da playlist; formatar o tempo da música (3:05). **Integração:** a busca consulta a API de músicas (simulada) e mostra a lista; adicionar música atualiza a playlist na tela. **E2E:** buscar música → adicionar à playlist → reproduzir.', 'Palavras-chave: 3 unitários (funções), 2 integração (componente + API/estado), 1 jornada E2E. Nota cheia (0,4): as 6 propostas coerentes com a camada. Metade (0,2): 3 a 5 coerentes, ou camadas misturadas. Zero (0): 2 ou menos coerentes.'),
      (v_atividade, 9, 3, 'Explique por que quanto mais alto na pirâmide o teste é mais lento e mais caro, e por que mesmo assim é preciso ter alguns testes E2E.', 0.4, 'Subindo na pirâmide, o teste envolve **mais partes** (navegador, rede, várias telas), por isso é **mais lento, mais caro** de escrever e manter e mais instável. Mesmo assim, alguns **E2E são necessários** porque são os únicos que testam o **fluxo completo como o usuário usa**, garantindo que as partes funcionam juntas nos **fluxos críticos**.', 'Palavras-chave: mais partes/dependências; lento e caro; fluxo completo; experiência do usuário; fluxos críticos. Nota cheia (0,4): por que é lento/caro + por que ainda é preciso ter E2E. Metade (0,2): só uma das duas partes. Zero (0): diz que E2E é mais rápido ou desnecessário.'),
      (v_atividade, 10, 1, 'Explique o que significa a responsabilidade (1.1) de quem desenvolve na qualidade do que entrega.', 0.2, 'Quem desenvolve é **responsável pela qualidade** do que entrega: **não marcar tarefa como pronta sem teste**, **relatar defeitos, inclusive os que causou**, e registrar falhas com dados para reproduzir.', 'Palavras-chave: responsável pela qualidade; não entregar sem teste; relatar os próprios defeitos. Nota cheia (0,2): conceito com pelo menos duas atitudes. Metade (0,1): uma atitude. Zero (0): passa a responsabilidade só para a equipe de testes.'),
      (v_atividade, 10, 2, 'Escreva o registro da falha com os quatro dados que permitem reproduzi-la: passos, dado usado, resultado obtido e resultado esperado.', 0.4, '**Passos:** abrir a loja, colocar um produto no carrinho, ir ao checkout, aplicar um cupom válido e clicar em "Finalizar compra". **Dado usado:** cupom (ex.: DESCONTO10) e produto (ex.: R$ 150,00). **Resultado obtido:** o botão não responde. **Resultado esperado:** o pedido é finalizado com o desconto aplicado e aparece a confirmação.', 'Palavras-chave: passos; dado usado (cupom); resultado obtido; resultado esperado. Nota cheia (0,4): os quatro dados. Metade (0,2): dois ou três dados. Zero (0): só "o checkout não funciona".'),
      (v_atividade, 10, 3, 'Responda ao colega justificando por que não se deve esconder o defeito, citando o custo do defeito e o risco para os clientes.', 0.4, 'Não se deve esconder porque o defeito **vai virar falha para os clientes** que usam cupom (**vendas perdidas**, reclamações) e, pela **Regra de 10 de Myers**, **fica mais caro** a cada fase que passa; corrigir agora custa pouco. Assumir o erro é **responsabilidade** e protege o cliente e a equipe.', 'Palavras-chave: falha para o cliente/vendas; custo cresce (Myers); responsabilidade/honestidade. Nota cheia (0,4): recusa esconder + custo + risco para os clientes. Metade (0,2): recusa com só um dos argumentos. Zero (0): concorda em esconder.');
end $$;
